@Component("inventoryItem-subscriber")
public class InventoryItemSubscriber extends BaseSubscriber {

	public InventoryItemSubscriber() {
	}
	
    public SubscriptionQueryResult<List<InventoryItem>, InventoryItem> inventoryItemSubscribe() {
        return queryGateway
                .subscriptionQuery(new FindAllInventoryItemQuery(), 
                		ResponseTypes.multipleInstancesOf(InventoryItem.class),
                		ResponseTypes.instanceOf(InventoryItem.class));
    }

    public SubscriptionQueryResult<InventoryItem, InventoryItem> inventoryItemSubscribe(@DestinationVariable UUID inventoryItemId) {
        return queryGateway
                .subscriptionQuery(new FindInventoryItemQuery(new LoadInventoryItemFilter(inventoryItemId)), 
                		ResponseTypes.instanceOf(InventoryItem.class),
                		ResponseTypes.instanceOf(InventoryItem.class));
    }





}

